static bool inputCaptureResolveMsiMotionSelector(const MachineIdentity& identity,HcMotionSelectorReceipt& receipt) {
    const auto* capability=ymcc::msi_sensor::motionCapability(identity.deviceClass,identity.product);
    if(!identity.resolved || identity.family!=YmccFamily::MsiClaw ||
        identity.manufacturer.find("MICRO-STAR")==std::string::npos || !capability ||
        identity.gyroMatrixId.rfind("hc-06c0b954:msi-claw-",0)!=0 ||
        identity.accelMatrixId.rfind("hc-06c0b954:msi-claw-",0)!=0) return false;
    receipt.attempted=true;receipt.resolved=true;
    receipt.dmiManufacturer=identity.manufacturer;receipt.dmiProduct=identity.product;
    receipt.dmiSystemProduct=identity.systemProduct;
    receipt.selectorId="msi-"+std::string(capability->boards[0]);
    receipt.deviceClass=identity.deviceClass;
    receipt.gyroMatrixId=identity.gyroMatrixId;receipt.accelMatrixId=identity.accelMatrixId;
    receipt.matrixSourceSha256=std::string(capability->frozenMatrixSourcesSha256);
    return true;
}

static bool inputCaptureMotionSelectorBound() {
    if(!g_hcMotionSelector.resolved) return false;
    if(inputCaptureGenericHcMotionRecipe(g_machineIdentity))return inputCaptureGenericHcMotionSelectorBound();
    if(ymcc::hc_default_motion::find(g_machineIdentity.deviceClass)) return inputCaptureDefaultHcMotionSelectorBound();
    if (ymcc::hc_model_motion::find(g_machineIdentity.deviceClass)) return inputCaptureNewHcMotionSelectorBound();
    if (ymcc::hc_legacy_motion::containsClass(g_machineIdentity.deviceClass)) return inputCaptureLegacyHcMotionSelectorBound();
    if(g_hcMotionSelector.selectorId=="asus-rc73xa" || g_hcMotionSelector.selectorId=="asus-rc73ya") return true;
    HcMotionSelectorReceipt current;
    return inputCaptureResolveMsiMotionSelector(g_machineIdentity,current) &&
        current.selectorId==g_hcMotionSelector.selectorId &&
        current.deviceClass==g_hcMotionSelector.deviceClass &&
        current.dmiProduct==g_hcMotionSelector.dmiProduct &&
        current.gyroMatrixId==g_hcMotionSelector.gyroMatrixId &&
        current.accelMatrixId==g_hcMotionSelector.accelMatrixId;
}

static void inputCaptureResolveHcMotionSelector() noexcept {
    if (g_hcMotionSelector.attempted) return;
    g_hcMotionSelector.attempted = true;
    if(inputCaptureResolveMsiMotionSelector(g_machineIdentity,g_hcMotionSelector)) return;
    if(inputCaptureResolveGenericHcMotionSelector(g_machineIdentity,g_hcMotionSelector)) return;
    try {
        if (ymcc::hc_default_motion::find(g_machineIdentity.deviceClass)) {
            (void)inputCaptureResolveDefaultHcMotionSelector(g_machineIdentity,g_hcMotionSelector);
            return;
        }
        if (ymcc::hc_model_motion::find(g_machineIdentity.deviceClass)) {
            (void)inputCaptureResolveNewHcMotionSelector(g_machineIdentity, g_hcMotionSelector);
            return;
        }
        if (inputCaptureResolveLegacyHcMotionSelector(g_machineIdentity, g_hcMotionSelector)) return;
        const std::string manufacturer = normalizeHcDmi(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"BaseBoardManufacturer"));
        const std::string product = normalizeHcDmi(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"BaseBoardProduct"));
        const std::string systemProduct = normalizeHcDmi(sgRegSZ(
            HKEY_LOCAL_MACHINE,
            L"HARDWARE\\DESCRIPTION\\System\\BIOS",
            L"SystemProductName"));
        g_hcMotionSelector.dmiManufacturer = manufacturer;
        g_hcMotionSelector.dmiProduct = product;
        g_hcMotionSelector.dmiSystemProduct = systemProduct;

        // C3 修复（2026-09-11）：ASUS 厂商判定收紧为 HC 精确串
        // （Devices/IDevice.cs:821-835 switch "ASUSTEK COMPUTER INC."），移除
        // "ASUSTE K COMPUTER INC." 与 find("ASUS") 放宽——motion selector 与
        // ymccResolveFamily 同一厂商事实，同套 HC 语义。normalizeHcDmi 已大写。
        const bool asus = manufacturer == "ASUSTEK COMPUTER INC.";
        if (!asus) return;

        // These two selectors are exact HC source cases.  Do not broaden this
        // match to a ROG PID family or a product-name substring: an unknown
        // SKU must remain unresolved rather than receive a guessed matrix.
        if (product == "RC73XA") {
            g_hcMotionSelector.resolved = true;
            g_hcMotionSelector.selectorId = "asus-rc73xa";
            g_hcMotionSelector.deviceClass = "HandheldCompanion.Devices.XboxROGAllyX";
            g_hcMotionSelector.gyroMatrixId =
                "hc-06c0b954:xbox-rog-ally-x:gyro:x-z-neg-y";
            g_hcMotionSelector.accelMatrixId =
                "hc-06c0b954:xbox-rog-ally-x:accel:neg-x-neg-z-y";
            g_hcMotionSelector.matrixSourceSha256 =
                "404987B6116C5DC79FEC80AABDF97D6E28F146EC2FFC3AF69ED8FC71E40FF8EE";
        } else if (product == "RC73YA") {
            g_hcMotionSelector.resolved = true;
            g_hcMotionSelector.selectorId = "asus-rc73ya";
            g_hcMotionSelector.deviceClass = "HandheldCompanion.Devices.XboxROGAlly";
            g_hcMotionSelector.gyroMatrixId =
                "hc-06c0b954:xbox-rog-ally:gyro:x-z-neg-y";
            g_hcMotionSelector.accelMatrixId =
                "hc-06c0b954:xbox-rog-ally:accel:neg-x-neg-z-y";
            g_hcMotionSelector.matrixSourceSha256 =
                "78BF90520419B63C6C8FD2BC12543B2D16280895802D8F9952849C4E030FE3D4";
        }
    } catch (...) {
        // A read-only diagnostic probe must never interfere with sensor input.
    }
}
